import{_ as a,o as t,c as n,a as s}from"./app.CYXXef1p.js";const u=JSON.parse('{"title":"Executive Brief - Storage Layer Language Selection","description":"","frontmatter":{"title":"Executive Brief - Storage Layer Language Selection","date":"2026-02-23T00:00:00.000Z","status":"DECISION_READY","owner":"architecture","tags":["executive-summary","language-selection","decision"]},"headers":[],"relativePath":"reference/EXECUTIVE_BRIEF_LANGUAGE_SELECTION.md","filePath":"reference/EXECUTIVE_BRIEF_LANGUAGE_SELECTION.md","lastUpdated":1771840873000}'),r={name:"reference/EXECUTIVE_BRIEF_LANGUAGE_SELECTION.md"};function i(o,e,l,c,d,p){return t(),n("div",null,[...e[0]||(e[0]=[s(`<h1 id="executive-brief-storage-layer-language-selection-14-5k-loc" tabindex="-1">Executive Brief: Storage Layer Language Selection (14.5K LOC) <a class="header-anchor" href="#executive-brief-storage-layer-language-selection-14-5k-loc" aria-label="Permalink to &quot;Executive Brief: Storage Layer Language Selection (14.5K LOC)&quot;">​</a></h1><p><strong>Decision:</strong> Rust (primary) or Go (secondary). Mojo not ready. Carbon eliminated.</p><hr><h2 id="the-ask" tabindex="-1">The Ask <a class="header-anchor" href="#the-ask" aria-label="Permalink to &quot;The Ask&quot;">​</a></h2><p>Replace 14.5K LOC of Python storage layer (PostgreSQL + Redis + Neo4j queries, HTTP handlers) with a compiled language. Which one?</p><hr><h2 id="bottom-line-recommendation" tabindex="-1">Bottom Line Recommendation <a class="header-anchor" href="#bottom-line-recommendation" aria-label="Permalink to &quot;Bottom Line Recommendation&quot;">​</a></h2><h3 id="primary-rust-axum-sqlx" tabindex="-1">PRIMARY: Rust + Axum/SQLx <a class="header-anchor" href="#primary-rust-axum-sqlx" aria-label="Permalink to &quot;PRIMARY: Rust + Axum/SQLx&quot;">​</a></h3><ul><li><strong>Timeline:</strong> 6-10 weeks</li><li><strong>Safety:</strong> Memory-safe by default (compile-time)</li><li><strong>Performance:</strong> C++ tier, no garbage collection pauses</li><li><strong>Cost:</strong> 3-6 weeks team training (offset by faster refactoring later)</li><li><strong>Risk:</strong> Low</li></ul><h3 id="secondary-go-gorm-sqlc" tabindex="-1">SECONDARY: Go + GORM/sqlc <a class="header-anchor" href="#secondary-go-gorm-sqlc" aria-label="Permalink to &quot;SECONDARY: Go + GORM/sqlc&quot;">​</a></h3><ul><li><strong>Timeline:</strong> 4-6 weeks (fastest option)</li><li><strong>Safety:</strong> GC pauses (1-10ms), no compile-time memory safety</li><li><strong>Performance:</strong> 2-3x slower than Rust (still fast for DB workloads)</li><li><strong>Cost:</strong> 1-2 weeks team training (simplest learning curve)</li><li><strong>Risk:</strong> Low</li></ul><p><strong>Choose Rust if:</strong> Long-term maintainability, performance predictability, safety matter more than time-to-market.</p><p><strong>Choose Go if:</strong> Time-to-market &lt; 6 weeks and GC overhead acceptable for your workload.</p><hr><h2 id="languages-not-ready" tabindex="-1">Languages NOT Ready <a class="header-anchor" href="#languages-not-ready" aria-label="Permalink to &quot;Languages NOT Ready&quot;">​</a></h2><h3 id="mojo-pre-1-0-late-2026" tabindex="-1">Mojo (Pre-1.0, Late 2026) <a class="header-anchor" href="#mojo-pre-1-0-late-2026" aria-label="Permalink to &quot;Mojo (Pre-1.0, Late 2026)&quot;">​</a></h3><ul><li><strong>Problem:</strong> 1.0 not until H1 2026; zero native database drivers; must use Python FFI for all DB operations</li><li><strong>Performance Cost:</strong> 2-4x slower than Rust/Go due to FFI overhead</li><li><strong>Verdict:</strong> Wait until 1.0 + ecosystem stabilization (late 2026)</li></ul><h3 id="carbon-pre-mvp-2028" tabindex="-1">Carbon (Pre-MVP, 2028+) <a class="header-anchor" href="#carbon-pre-mvp-2028" aria-label="Permalink to &quot;Carbon (Pre-MVP, 2028+)&quot;">​</a></h3><ul><li><strong>Problem:</strong> MVP 0.1 not until Dec 2026 at earliest; 1.0 not until after 2028; zero ecosystem</li><li><strong>Verdict:</strong> Eliminated. Not viable for any 2026 timeline.</li></ul><h3 id="zig-1-0-in-2026-ecosystem-emerging" tabindex="-1">Zig (1.0 in 2026, Ecosystem Emerging) <a class="header-anchor" href="#zig-1-0-in-2026-ecosystem-emerging" aria-label="Permalink to &quot;Zig (1.0 in 2026, Ecosystem Emerging)&quot;">​</a></h3><ul><li><strong>Status:</strong> 1.0 landing sometime in 2026; real production backend built in Feb 2026</li><li><strong>Problem:</strong> Ecosystem less mature than Rust/Go; fewer proven DB libraries</li><li><strong>Verdict:</strong> Viable but risky. Wait for 1.0 release + ecosystem stabilization, or commit to writing some custom drivers.</li></ul><hr><h2 id="quick-comparison-storage-layer-workload" tabindex="-1">Quick Comparison (Storage Layer Workload) <a class="header-anchor" href="#quick-comparison-storage-layer-workload" aria-label="Permalink to &quot;Quick Comparison (Storage Layer Workload)&quot;">​</a></h2><table tabindex="0"><thead><tr><th>Factor</th><th style="text-align:center;">Rust</th><th style="text-align:center;">Go</th><th style="text-align:center;">Mojo</th><th style="text-align:center;">Carbon</th><th style="text-align:center;">Zig</th></tr></thead><tbody><tr><td><strong>Production Ready</strong></td><td style="text-align:center;">✅</td><td style="text-align:center;">✅</td><td style="text-align:center;">❌</td><td style="text-align:center;">❌</td><td style="text-align:center;">⚠️</td></tr><tr><td><strong>PostgreSQL Driver</strong></td><td style="text-align:center;">🥇 pgx</td><td style="text-align:center;">🥈 pgx/sqlc</td><td style="text-align:center;">❌ FFI</td><td style="text-align:center;">❌ None</td><td style="text-align:center;">⚠️ pg.zig</td></tr><tr><td><strong>Redis Support</strong></td><td style="text-align:center;">✅ Excellent</td><td style="text-align:center;">✅ Excellent</td><td style="text-align:center;">❌ FFI</td><td style="text-align:center;">❌ None</td><td style="text-align:center;">⚠️ Limited</td></tr><tr><td><strong>Neo4j Support</strong></td><td style="text-align:center;">✅ Good</td><td style="text-align:center;">✅ Excellent</td><td style="text-align:center;">❌ FFI</td><td style="text-align:center;">❌ None</td><td style="text-align:center;">❌ None</td></tr><tr><td><strong>Performance</strong></td><td style="text-align:center;">🥇 C++ tier</td><td style="text-align:center;">🥈 2-3x slower</td><td style="text-align:center;">❌ FFI slow</td><td style="text-align:center;">❌ Unknown</td><td style="text-align:center;">🥇 C++ tier</td></tr><tr><td><strong>Dev Velocity</strong></td><td style="text-align:center;">⚠️ 2-3 weeks</td><td style="text-align:center;">✅ 1-2 weeks</td><td style="text-align:center;">✅ Python</td><td style="text-align:center;">❌ N/A</td><td style="text-align:center;">⚠️ 2-3 weeks</td></tr><tr><td><strong>Maturity</strong></td><td style="text-align:center;">✅ Excellent</td><td style="text-align:center;">✅ Excellent</td><td style="text-align:center;">❌ Minimal</td><td style="text-align:center;">❌ None</td><td style="text-align:center;">⚠️ Growing</td></tr><tr><td><strong>Learning Curve</strong></td><td style="text-align:center;">❌ Steep</td><td style="text-align:center;">✅ Gentle</td><td style="text-align:center;">✅ Python-like</td><td style="text-align:center;">❌ N/A</td><td style="text-align:center;">⚠️ Moderate</td></tr><tr><td><strong>Long-term Risk</strong></td><td style="text-align:center;">🟢 Low</td><td style="text-align:center;">🟢 Low</td><td style="text-align:center;">🔴 High</td><td style="text-align:center;">🔴 Critical</td><td style="text-align:center;">🟡 Medium</td></tr></tbody></table><hr><h2 id="decision-criteria" tabindex="-1">Decision Criteria <a class="header-anchor" href="#decision-criteria" aria-label="Permalink to &quot;Decision Criteria&quot;">​</a></h2><h3 id="if-you-prioritize-safety-long-term-maintainability" tabindex="-1">If you prioritize: <strong>Safety + Long-term Maintainability</strong> <a class="header-anchor" href="#if-you-prioritize-safety-long-term-maintainability" aria-label="Permalink to &quot;If you prioritize: **Safety + Long-term Maintainability**&quot;">​</a></h3><p>→ <strong>Choose Rust</strong></p><ul><li>Compile-time memory safety</li><li>Predictable performance (no GC pauses)</li><li>Better refactoring confidence on large codebases</li><li>Industry momentum (Stripe, Discord, AWS, Google)</li></ul><h3 id="if-you-prioritize-time-to-market-simplicity" tabindex="-1">If you prioritize: <strong>Time-to-Market + Simplicity</strong> <a class="header-anchor" href="#if-you-prioritize-time-to-market-simplicity" aria-label="Permalink to &quot;If you prioritize: **Time-to-Market + Simplicity**&quot;">​</a></h3><p>→ <strong>Choose Go</strong></p><ul><li>4-6 week timeline (vs 6-10 for Rust)</li><li>Gentler learning curve (1-2 weeks)</li><li>Proven at massive scale (Google, Uber, Kubernetes)</li><li>GC overhead acceptable for most web workloads</li></ul><h3 id="if-you-prioritize-performance-at-any-cost-memory-efficiency" tabindex="-1">If you prioritize: <strong>Performance at Any Cost + Memory Efficiency</strong> <a class="header-anchor" href="#if-you-prioritize-performance-at-any-cost-memory-efficiency" aria-label="Permalink to &quot;If you prioritize: **Performance at Any Cost + Memory Efficiency**&quot;">​</a></h3><p>→ <strong>Choose Rust</strong> (Zig in 2027+ after 1.0 ecosystem stabilizes)</p><ul><li>Zero GC pauses</li><li>C++ tier performance</li><li>Fine-grained memory control</li><li>Risk: Zig ecosystem still emerging in 2026</li></ul><hr><h2 id="risk-summary" tabindex="-1">Risk Summary <a class="header-anchor" href="#risk-summary" aria-label="Permalink to &quot;Risk Summary&quot;">​</a></h2><h3 id="rust-risks" tabindex="-1">Rust Risks <a class="header-anchor" href="#rust-risks" aria-label="Permalink to &quot;Rust Risks&quot;">​</a></h3><ul><li><strong>Steep learning curve</strong> — 3-6 weeks for team proficiency (medium risk, manageable)</li><li><strong>Slower initial dev</strong> — Week 1-3 slower; offsets in weeks 4-10 (low risk, expected)</li><li><strong>Compile times</strong> — Longer than Go but not prohibitive (low risk)</li></ul><h3 id="go-risks" tabindex="-1">Go Risks <a class="header-anchor" href="#go-risks" aria-label="Permalink to &quot;Go Risks&quot;">​</a></h3><ul><li><strong>GC pauses</strong> — 1-10ms pauses under load (low risk for most workloads, acceptable tradeoff)</li><li><strong>No memory safety</strong> — Code review rigor required (manageable with discipline)</li></ul><h3 id="mojo-risks-why-not" tabindex="-1">Mojo Risks (Why Not) <a class="header-anchor" href="#mojo-risks-why-not" aria-label="Permalink to &quot;Mojo Risks (Why Not)&quot;">​</a></h3><ul><li><strong>Pre-1.0 instability</strong> — Breaking changes expected (high risk)</li><li><strong>FFI overhead</strong> — 2-4x slower for all DB operations (critical issue for your workload)</li><li><strong>Ecosystem gap</strong> — No native drivers, must use Python (negates performance benefits)</li></ul><h3 id="carbon-risks-why-eliminated" tabindex="-1">Carbon Risks (Why Eliminated) <a class="header-anchor" href="#carbon-risks-why-eliminated" aria-label="Permalink to &quot;Carbon Risks (Why Eliminated)&quot;">​</a></h3><ul><li><strong>Years from production</strong> — MVP 0.1 in Dec 2026, 1.0 after 2028 (critical blocker)</li><li><strong>Zero ecosystem</strong> — No frameworks, drivers, or libraries (critical blocker)</li></ul><h3 id="zig-risks-why-conditional" tabindex="-1">Zig Risks (Why Conditional) <a class="header-anchor" href="#zig-risks-why-conditional" aria-label="Permalink to &quot;Zig Risks (Why Conditional)&quot;">​</a></h3><ul><li><strong>1.0 timing uncertain</strong> — &quot;Sometime in 2026&quot; is vague (medium risk)</li><li><strong>Smaller ecosystem</strong> — Fewer battle-tested libraries than Rust/Go (medium risk)</li><li><strong>Async model unproven</strong> — Different from traditional async/await (medium risk)</li><li><strong>Mitigation:</strong> Wait for 1.0 + 2-3 months post-release stabilization (late 2026)</li></ul><hr><h2 id="performance-reality-14-5k-loc-storage-layer" tabindex="-1">Performance Reality (14.5K LOC Storage Layer) <a class="header-anchor" href="#performance-reality-14-5k-loc-storage-layer" aria-label="Permalink to &quot;Performance Reality (14.5K LOC Storage Layer)&quot;">​</a></h2><p><strong>Critical insight:</strong> Your bottleneck is <strong>database network I/O (5-50ms)</strong>, not CPU:</p><div class="language- vp-adaptive-theme line-numbers-mode"><button title="Copy Code" class="copy"></button><span class="lang"></span><pre class="shiki shiki-themes github-light github-dark vp-code" tabindex="0"><code><span class="line"><span>PostgreSQL query latency:      5-20ms  (network/DB dominant)</span></span>
<span class="line"><span>JSON parsing overhead:          0.5-1ms  (negligible, even with Mojo)</span></span>
<span class="line"><span>Redis cache hit:               1-5ms   (network dominant)</span></span>
<span class="line"><span>Neo4j traversal:               5-20ms  (network dominant)</span></span>
<span class="line"><span>HTTP round-trip:               50-200ms (cumulative of above)</span></span>
<span class="line"><span></span></span>
<span class="line"><span>Result:</span></span>
<span class="line"><span>  Rust vs Go difference:    ~0.5-2ms (5-10% impact, unmeasurable)</span></span>
<span class="line"><span>  Rust vs Mojo difference: ~2-8ms   (but Mojo not production-ready)</span></span>
<span class="line"><span>  Rust vs Zig difference:  ~0ms     (parity on DB workloads)</span></span>
<span class="line"><span></span></span>
<span class="line"><span>BOTTOM LINE: All three (Rust/Go/Zig) are fast enough. </span></span>
<span class="line"><span>             Choose based on MATURITY + RISK, not raw speed.</span></span></code></pre><div class="line-numbers-wrapper" aria-hidden="true"><span class="line-number">1</span><br><span class="line-number">2</span><br><span class="line-number">3</span><br><span class="line-number">4</span><br><span class="line-number">5</span><br><span class="line-number">6</span><br><span class="line-number">7</span><br><span class="line-number">8</span><br><span class="line-number">9</span><br><span class="line-number">10</span><br><span class="line-number">11</span><br><span class="line-number">12</span><br><span class="line-number">13</span><br></div></div><p><strong>MLIR/SIMD Not a Factor:</strong> Mojo&#39;s MLIR advantages apply to numeric/algorithmic workloads (JSON parsing: 52% faster). For DB layers, you&#39;re I/O-bound; MLIR helps nothing. FFI overhead negates any parsing gains.</p><hr><h2 id="timeline-effort" tabindex="-1">Timeline &amp; Effort <a class="header-anchor" href="#timeline-effort" aria-label="Permalink to &quot;Timeline &amp; Effort&quot;">​</a></h2><h3 id="rust-axum-sqlx-recommended" tabindex="-1">Rust + Axum/SQLx (Recommended) <a class="header-anchor" href="#rust-axum-sqlx-recommended" aria-label="Permalink to &quot;Rust + Axum/SQLx (Recommended)&quot;">​</a></h3><div class="language- vp-adaptive-theme line-numbers-mode"><button title="Copy Code" class="copy"></button><span class="lang"></span><pre class="shiki shiki-themes github-light github-dark vp-code" tabindex="0"><code><span class="line"><span>Week 1-2:  Team Rust fundamentals (async/ownership/borrowing)</span></span>
<span class="line"><span>Week 3-4:  PostgreSQL ORM layer (SQLx + connection pooling)</span></span>
<span class="line"><span>Week 5-6:  Redis + Neo4j integration</span></span>
<span class="line"><span>Week 7-8:  HTTP handlers (Axum framework)</span></span>
<span class="line"><span>Week 9-10: Perf testing + production hardening</span></span>
<span class="line"><span>Total: 6-10 weeks, 40-60 person-days</span></span></code></pre><div class="line-numbers-wrapper" aria-hidden="true"><span class="line-number">1</span><br><span class="line-number">2</span><br><span class="line-number">3</span><br><span class="line-number">4</span><br><span class="line-number">5</span><br><span class="line-number">6</span><br></div></div><h3 id="go-gorm-sqlc-faster" tabindex="-1">Go + GORM/sqlc (Faster) <a class="header-anchor" href="#go-gorm-sqlc-faster" aria-label="Permalink to &quot;Go + GORM/sqlc (Faster)&quot;">​</a></h3><div class="language- vp-adaptive-theme line-numbers-mode"><button title="Copy Code" class="copy"></button><span class="lang"></span><pre class="shiki shiki-themes github-light github-dark vp-code" tabindex="0"><code><span class="line"><span>Week 1:    Setup + sqlc code generation</span></span>
<span class="line"><span>Week 2-3:  PostgreSQL ORM (GORM models + migrations)</span></span>
<span class="line"><span>Week 4:    Redis + Neo4j integration</span></span>
<span class="line"><span>Week 5:    HTTP handlers (Gin or Chi)</span></span>
<span class="line"><span>Week 6:    Testing + production hardening</span></span>
<span class="line"><span>Total: 4-6 weeks, 20-30 person-days</span></span></code></pre><div class="line-numbers-wrapper" aria-hidden="true"><span class="line-number">1</span><br><span class="line-number">2</span><br><span class="line-number">3</span><br><span class="line-number">4</span><br><span class="line-number">5</span><br><span class="line-number">6</span><br></div></div><hr><h2 id="team-implications" tabindex="-1">Team Implications <a class="header-anchor" href="#team-implications" aria-label="Permalink to &quot;Team Implications&quot;">​</a></h2><h3 id="rust-route" tabindex="-1">Rust Route <a class="header-anchor" href="#rust-route" aria-label="Permalink to &quot;Rust Route&quot;">​</a></h3><ul><li><strong>Training cost:</strong> $50K-100K (team ramp-up, mentoring)</li><li><strong>Hiring impact:</strong> Easier future recruiting in Rust market</li><li><strong>Productivity:</strong> Slower weeks 1-4, faster weeks 5+</li><li><strong>Confidence:</strong> Higher long-term (memory safety at compile-time)</li></ul><h3 id="go-route" tabindex="-1">Go Route <a class="header-anchor" href="#go-route" aria-label="Permalink to &quot;Go Route&quot;">​</a></h3><ul><li><strong>Training cost:</strong> $10K-20K (simpler language)</li><li><strong>Hiring impact:</strong> Neutral (Go widely known)</li><li><strong>Productivity:</strong> Steady fast throughout</li><li><strong>Confidence:</strong> Moderate (GC pauses, human discipline required)</li></ul><hr><h2 id="recommendation-decision-tree" tabindex="-1">Recommendation Decision Tree <a class="header-anchor" href="#recommendation-decision-tree" aria-label="Permalink to &quot;Recommendation Decision Tree&quot;">​</a></h2><div class="language- vp-adaptive-theme line-numbers-mode"><button title="Copy Code" class="copy"></button><span class="lang"></span><pre class="shiki shiki-themes github-light github-dark vp-code" tabindex="0"><code><span class="line"><span>Need result in &lt; 5 weeks?</span></span>
<span class="line"><span>  YES → Go only choice</span></span>
<span class="line"><span>  NO  → Continue below</span></span>
<span class="line"><span></span></span>
<span class="line"><span>Can invest 3-6 weeks in team training?</span></span>
<span class="line"><span>  NO  → Go (faster ramp-up)</span></span>
<span class="line"><span>  YES → Continue below</span></span>
<span class="line"><span></span></span>
<span class="line"><span>Safety/predictability &gt; time-to-market?</span></span>
<span class="line"><span>  YES → Rust (recommended)</span></span>
<span class="line"><span>  NO  → Go (acceptable)</span></span>
<span class="line"><span></span></span>
<span class="line"><span>Want finest performance control?</span></span>
<span class="line"><span>  YES → Rust or Zig (wait for 1.0)</span></span>
<span class="line"><span>  NO  → Go (good enough)</span></span></code></pre><div class="line-numbers-wrapper" aria-hidden="true"><span class="line-number">1</span><br><span class="line-number">2</span><br><span class="line-number">3</span><br><span class="line-number">4</span><br><span class="line-number">5</span><br><span class="line-number">6</span><br><span class="line-number">7</span><br><span class="line-number">8</span><br><span class="line-number">9</span><br><span class="line-number">10</span><br><span class="line-number">11</span><br><span class="line-number">12</span><br><span class="line-number">13</span><br><span class="line-number">14</span><br><span class="line-number">15</span><br></div></div><hr><h2 id="final-call" tabindex="-1">Final Call <a class="header-anchor" href="#final-call" aria-label="Permalink to &quot;Final Call&quot;">​</a></h2><h3 id="primary-recommendation-rust-axum-sqlx" tabindex="-1"><strong>PRIMARY RECOMMENDATION: Rust + Axum/SQLx</strong> <a class="header-anchor" href="#primary-recommendation-rust-axum-sqlx" aria-label="Permalink to &quot;**PRIMARY RECOMMENDATION: Rust + Axum/SQLx**&quot;">​</a></h3><ul><li>Safest long-term choice</li><li>Best database driver ecosystem</li><li>Zero GC pauses (predictable latency)</li><li>Compile-time memory safety (fewer bugs)</li><li>Team investment pays dividends on future refactoring</li></ul><h3 id="acceptable-alternative-go-gorm-sqlc" tabindex="-1"><strong>ACCEPTABLE ALTERNATIVE: Go + GORM/sqlc</strong> <a class="header-anchor" href="#acceptable-alternative-go-gorm-sqlc" aria-label="Permalink to &quot;**ACCEPTABLE ALTERNATIVE: Go + GORM/sqlc**&quot;">​</a></h3><ul><li>Fastest time-to-market</li><li>Proven at Google/Uber/Kubernetes scale</li><li>Simpler learning curve</li><li>GC pauses acceptable for most web workloads</li><li>Choose if timeline pressure &gt; 5 weeks</li></ul><h3 id="not-ready-mojo" tabindex="-1"><strong>NOT READY: Mojo</strong> <a class="header-anchor" href="#not-ready-mojo" aria-label="Permalink to &quot;**NOT READY: Mojo**&quot;">​</a></h3><ul><li>Pre-1.0 instability</li><li>FFI overhead defeats performance benefits</li><li>No native drivers (Python interop costs)</li><li>Re-evaluate late 2026 + 6 months ecosystem maturation</li></ul><h3 id="eliminated-carbon" tabindex="-1"><strong>ELIMINATED: Carbon</strong> <a class="header-anchor" href="#eliminated-carbon" aria-label="Permalink to &quot;**ELIMINATED: Carbon**&quot;">​</a></h3><ul><li>MVP 0.1 not until Dec 2026</li><li>1.0 not until 2028+</li><li>Zero ecosystem</li><li>Not viable for any 2026 timeline</li></ul><h3 id="conditional-zig-post-1-0-late-2026" tabindex="-1"><strong>CONDITIONAL: Zig (Post-1.0 Late 2026)</strong> <a class="header-anchor" href="#conditional-zig-post-1-0-late-2026" aria-label="Permalink to &quot;**CONDITIONAL: Zig (Post-1.0 Late 2026)**&quot;">​</a></h3><ul><li>1.0 expected 2026 (timing uncertain)</li><li>Viable but emerging ecosystem</li><li>Consider if Rust learning curve blocking factor</li><li>Risk: Commit to writing some custom DB drivers</li></ul><hr><h2 id="implementation-checklist" tabindex="-1">Implementation Checklist <a class="header-anchor" href="#implementation-checklist" aria-label="Permalink to &quot;Implementation Checklist&quot;">​</a></h2><ul><li>[ ] <strong>Architecture Review:</strong> Present Rust vs Go tradeoff to stakeholders</li><li>[ ] <strong>Team Decision:</strong> Safety vs Speed — which matters more?</li><li>[ ] <strong>POC/Spike:</strong> 3-5 day Rust spike (basic DB query + Redis)</li><li>[ ] <strong>Cost Estimate:</strong> Rust 40-60 person-days, Go 20-30 person-days</li><li>[ ] <strong>Training Plan:</strong> Rust ramp-up curriculum (3-6 weeks), Go simpler</li><li>[ ] <strong>Go/No-Go Decision:</strong> Proceed with chosen language</li><li>[ ] <strong>Project Kickoff:</strong> Initiate 6-10 week (Rust) or 4-6 week (Go) sprint</li></ul><hr><h2 id="sources-references" tabindex="-1">Sources &amp; References <a class="header-anchor" href="#sources-references" aria-label="Permalink to &quot;Sources &amp; References&quot;">​</a></h2><ul><li><a href="https://docs.modular.com/mojo/roadmap/" target="_blank" rel="noreferrer">Mojo Roadmap</a> — 1.0 H1 2026</li><li><a href="https://github.com/carbon-language/carbon-lang/blob/trunk/docs/project/roadmap.md" target="_blank" rel="noreferrer">Carbon Roadmap</a> — 0.1 Q4 2026</li><li><a href="https://lalinsky.com/2026/02/19/six-months-of-yak-shaving-a-zig-web-backend-stack.html" target="_blank" rel="noreferrer">Zig Web Backend (Feb 2026)</a> — Production backend</li><li><a href="https://aarambhdevhub.medium.com/rust-web-frameworks-in-2026-axum-vs-actix-web-rocket-vs-warp-vs-salvo-which-one-should-you-2db3792c79a2" target="_blank" rel="noreferrer">Rust Web Frameworks (2026)</a> — Axum ecosystem</li><li><a href="https://encore.cloud/resources/go-orms" target="_blank" rel="noreferrer">Go ORM Comparison (2026)</a> — pgx/sqlc/GORM comparison</li><li><a href="https://medium.com/@the_atomic_architect/we-ran-go-rust-postgresql-and-kubernetes-in-production-for-two-years-heres-what-actually-78d99b2b9020" target="_blank" rel="noreferrer">Go Production Case Study (Feb 2026)</a> — 2-year production report</li></ul><hr><p><strong>Prepared by:</strong> Architecture Research <strong>Date:</strong> February 23, 2026 <strong>Status:</strong> Decision Ready <strong>Next Step:</strong> Stakeholder review + team decision (Rust or Go)</p>`,87)])])}const g=a(r,[["render",i]]);export{u as __pageData,g as default};
